// Native Skia Canvas adapter: renders the same deterministic browser scene without a browser socket.
const {createCanvas,GlobalFonts}=require('@napi-rs/canvas');const fs=require('fs'),path=require('path'),vm=require('vm'),{spawn}=require('child_process');
const root=path.resolve(__dirname,'..');GlobalFonts.registerFromPath(root+'/assets/NotoSerif-Regular.ttf','Latin');GlobalFonts.registerFromPath(root+'/assets/NotoSerif-Italic.ttf','Latin');GlobalFonts.registerFromPath(root+'/assets/NotoSerifCJK-Regular.ttc','CJK');
const canvas=createCanvas(1920,1080);global.document={querySelector:()=>canvas,createElement:()=>createCanvas(1,1),fonts:{ready:Promise.resolve()}};global.window=global;vm.runInThisContext(fs.readFileSync(root+'/src/film.js','utf8'));
(async()=>{await document.fonts.ready;let mode=process.argv[2]||'stills';
if(mode==='stills'){for(const t of [0,3,6,10,13,15.4,16.2,17,17.8,18.6,20,23.5,27,31,35.5]){render(t);fs.writeFileSync(root+'/qa/frame-'+t.toFixed(2)+'.png',canvas.toBuffer('image/png'));}console.log('stills complete')}
if(mode==='video'){const f=spawn('ffmpeg',['-y','-v','warning','-f','image2pipe','-vcodec','mjpeg','-r','24','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','17','-pix_fmt','yuv420p','-movflags','+faststart',root+'/picture.mp4'],{stdio:['pipe','inherit','inherit']});const closed=new Promise((res,rej)=>f.on('close',c=>c===0?res():rej(new Error('ffmpeg '+c))));for(let i=0;i<864;i++){render(i/24);let b=canvas.toBuffer('image/jpeg',95);if(!f.stdin.write(b))await new Promise(r=>f.stdin.once('drain',r));if(i%120===0)console.log(i+'/864');}f.stdin.end();await closed;console.log('picture render complete')}
if(mode==='strip'){for(let i=0;i<=23;i++){let t=14.6+i*.2;render(t);fs.writeFileSync(root+'/qa/action-'+t.toFixed(2)+'.jpg',canvas.toBuffer('image/jpeg',90));}}
if(mode==='determinism'){render(20);let a=canvas.toBuffer('image/png');render(2);render(20);let b=canvas.toBuffer('image/png');fs.writeFileSync(root+'/qa/determinism.json',JSON.stringify({identical:a.equals(b),bytes:a.length}));}
fs.writeFileSync(root+'/events.json',JSON.stringify({duration:DUR,events:EV},null,2));})().catch(e=>{console.error(e);process.exit(1)});
